const A=2,C=0.4,K=0.5,R=0.12,RG=0.08,HX=2,HZ=2.5,MAXS=200,X0=1.5,Z0=2;
const cl=(v,m)=>Math.max(-m,Math.min(m,v));
const rnd=n=>{const s=Math.sin(n*12.9898+78.233)*43758.5453;return s-Math.floor(s);};
function batch(k,b,seed){const idx=ALL.slice();for(let i=0;i<b;i++){const j=i+Math.min(19-i,Math.floor(rnd(seed*7.1+k*31.7+i*1.37)*(20-i)));const t=idx[i];idx[i]=idx[j];idx[j]=t;}return idx.slice(0,b);}
function grad(x,z,ids){let gx=0,gz=0,l=0;for(const i of ids){const dx=x-CX[i],dz=z-CZ[i];gx+=A*dx;gz+=C*dz;l+=0.5*(A*dx*dx+C*dz*dz);}const n=ids.length;return [gx/n,gz/n,l/n];}
const full=(x,z)=>grad(x,z,ALL)[2];
const bs=inp=>Math.max(1,Math.min(20,Math.round(inp.batch_size)));
function move(x,z,dx,dz){const nx=x+dx,nz=z+dz;return [cl(nx,HX),cl(nz,HZ),Math.abs(nx)>HX||Math.abs(nz)>HZ];}
const done=s=>s.div||s.step>=MAXS;
function advance(s,inp,seed){
 if(done(s))return {...s,on:false};
 const lr=inp.learning_rate,g=grad(s.x,s.z,batch(s.step,bs(inp),seed));
 const [x,z,div]=move(s.x,s.z,-lr*g[0],-lr*g[1]);
 let gx=s.gx,gz=s.gz,gd=s.gdiv;
 if(!gd){const h=grad(gx,gz,ALL);[gx,gz,gd]=move(gx,gz,-lr*h[0],-lr*h[1]);}
 const step=s.step+1;
 const n={...s,x,z,gx,gz,div,gdiv:gd,step,bl:g[2],path:s.path.concat([[x,z]]).slice(-201),gpath:s.gpath.concat([[gx,gz]]).slice(-201)};
 n.on=s.on&&!done(n);return n;
}
export function initialState(){return {x:X0,z:Z0,gx:X0,gz:Z0,step:0,on:false,div:false,gdiv:false,bl:0,path:[[X0,Z0]],gpath:[[X0,Z0]]};}
export function reduce({state:s,event:e,inputs,seed}){
 if(e.type==='step')return !s.on||e.tick%3?s:advance(s,inputs,seed);
 if((e.type==='drag_move'||e.type==='drag_end')&&e.node==='ball'){if(s.step>0)return s;const x=cl(e.value,1.9);return {...s,x,gx:x,path:[[x,s.z]],gpath:[[x,s.gz]]};}
 if(e.type!=='action')return s;
 if(e.action==='run')return done(s)?s:{...s,on:true};
 if(e.action==='pause')return {...s,on:false};
 if(e.action==='stepOnce')return advance({...s,on:false},inputs,seed);
 if(e.action==='clearTrail')return {...s,path:[[s.x,s.z]],gpath:[[s.gx,s.gz]]};
 return s;
}
function aim(dx,dz,shown){const v=Math.hypot(dx,dz),h=Math.SQRT1_2;return shown&&v>1e-6?{visible:true,quaternion:[dz/v*h,0,-dx/v*h,h],scale:[1,v,1]}:{visible:false};}
const lift=p=>[p[0],K*full(p[0],p[1])+0.04,p[1]];
export function evaluate({inputs,state,seed}){
 const s=state||initialState(),lr=inputs.learning_rate,live=!done(s),show=!!inputs.show_full_gd,L=full(s.x,s.z);
 const g=grad(s.x,s.z,batch(s.step,bs(inputs),seed)),h=grad(s.x,s.z,ALL);
 const st=s.div?'diverged':s.step>=MAXS?(L-0.24<0.05?'converged':'finished'):s.on?'running':'paused';
 const r={loss:L,steps:s.step,status:st};if(s.step>0)r.batchLoss=s.bl;
 return {nodes:{
  ball:{position:[s.x,K*L+R,s.z]},
  gdBall:{position:[s.gx,K*full(s.gx,s.gz)+RG,s.gz],visible:show},
  batchArrow:aim(-lr*g[0],-lr*g[1],live),
  fullArrow:aim(-lr*h[0],-lr*h[1],live),
  sgdTrail:{points:s.path.map(lift)},
  gdTrail:{points:s.gpath.map(lift),visible:show}
 },readouts:r};
}

